test(`localStorage.removeItem('ultimo-tratto-run-v2');meta.paths=undefined;pathMapIdx=0;startMap('spirale');assert(pathMapIdx===0,'locked map does not start');startMap('pagina');assert(gameMode==='paths'&&towers.length===curMap().sockets.length&&!towers.some(t=>t.type),'empty sockets');const p=slot(3);assert(p.x===curMap().sockets[3][0]&&p.y===curMap().sockets[3][1],'slot follows socket');selected=0;assert(!build('sniper'),'locked defense');selected=0;assert(build('lab'),'lab on socket');assert(techEntries().every(([k])=>!PATH_HIDDEN_TECH.includes(k)&&(!DEFENSES[k]||curMap().allow.includes(k))),'lab lists only path-compatible research');ink=500;selected=1;assert(build('triangle'),'triangle');phase='build';startWave();assert(queue.length>0&&queue.every(q=>q.path===0&&!['roller','setSquare'].includes(q.type)),'path queue without polar bosses');spawnTimer=0;update(.05);const e=enemies[0];assert(e&&e.onPath&&e.t>0,'enemy walks along the road');const x0=e.px,y0=e.py;for(let i=0;i<40;i++)update(.05);assert(Math.hypot(e.px-x0,e.py-y0)>10,'enemy advances');const q={x:CX+Math.cos(e.a)*e.r,y:CY+Math.sin(e.a)*e.r};assert(Math.hypot(q.x-e.px,q.y-e.py)<1e-6,'polar position matches road position');console.log('PASS: path mode setup, locks, sockets, spawning and movement')`)
test(`localStorage.removeItem('ultimo-tratto-run-v2');meta.paths=undefined;startMap('pagina');towers.forEach(t=>t.type=null);enemies=[];queue=[];phase='wave';const e=spawnPathEnemy('pink',0,pathData(0).len-1);const before=core;updatePathEnemy(e,.5);assert(e.dead&&core<before,'leak damages the spark');startMap('pagina');enemies=[];phase='wave';queue=[];const s=spawnPathEnemy('splitter',0,300);hurtEnemy(s,9999,true);assert(enemies.filter(x=>x.type==='mini'&&x.onPath&&x.path===0).length===2,'splitter crumbs stay on the road');startMap('pagina');enemies=[];phase='wave';queue=[];const a=spawnPathEnemy('pink',0,500),b=spawnPathEnemy('pink',0,300);const order=[b,a].sort(targetOrder({priority:'first'}));assert(order[0]===a,'first target is the furthest along the road');powerCharges.pulse=1;tech.pulse=true;usePulse();assert(a.t<=430.001&&a.t<500,'pulse pushes enemies back along the road');console.log('PASS: path leaks, splitting, target order, pulse')`)
test(`localStorage.removeItem('ultimo-tratto-run-v2');meta.paths=undefined;startMap('pagina');tech={triangle:true,spiral:true,mortar:true};playerLevel=3;playerXP=10;wave=curMap().waves;core=90;phase='wave';enemies=[];queue=[];waveComplete();assert(over&&phase==='won','last wave wins the map');const pm=pathMeta();assert(pm.cleared.pagina===3&&pm.tech.spiral&&pm.level===3,'stars, research and level saved');startMap('spirale');assert(curMap().id==='spirale'&&tech.spiral&&tech.mortar&&playerLevel===3,'progress carries to the next map');startMap('spirale');core=0;lose();assert(over&&phase==='lost','losing a path map ends the run');for(const g of ['classic','25d']){setPref('gfx',g,true);for(const m of MAPS){pathMeta().cleared[m.id]=1}for(const m of MAPS){startMap(m.id);ink=900;towers.forEach((t,i)=>{selected=i;build(i?'triangle':'lab')});startWave();for(let i=0;i<120;i++)update(.05);fitView();applyView();draw();selected=2;draw()}}assert(localStorage.getItem('ultimo-tratto-run-v2')===null,'path mode never saves a polar run');console.log('PASS: path victory, progression across maps, defeat, rendering of every map in both graphics modes')`)
test(`localStorage.removeItem('ultimo-tratto-run-v2');meta.paths=undefined;pathMapIdx=0;startMap('pagina');ink=900;selected=1;build('triangle');phase='wave';enemies=[];queue=[];const near=slot(1);const e=spawnPathEnemy('pink',0,0);let best=1e9,bt=0;for(let t=0;t<pathData(0).len;t+=2){const q=pathAt(pathData(0),t);const d=Math.hypot(q.x-near.x,q.y-near.y);if(d<best){best=d;bt=t}}e.t=bt;setPathPos(e);const hp0=towers[1].hp;updatePathEnemy(e,1);assert(e.biting&&towers[1].hp<hp0,'enemy bites the nearby defense instead of walking past');const t0=e.t;updatePathEnemy(e,1);assert(e.t===t0,'enemy stays to bite');pathMeta().cleared.pagina=1;startMap('spirale');tech.mender=true;ink=900;let pa=0,pb=1,pd=1e9;for(let x=0;x<towers.length;x++)for(let y=x+1;y<towers.length;y++){const d=dist(slot(x),slot(y));if(d<pd){pd=d;pa=x;pb=y}}selected=pa;build('triangle');selected=pb;build('mender');enemies=[];towers[pa].hp=20;towers[pb].cooldown=0;PATH_TUNE.range=2;updateDefenses(.1);assert(towers[pa].hp>20,'mender repairs defenses in range');PATH_TUNE.range=.5;console.log('PASS: path enemies bite nearby defenses, mender repairs them')`)
test(`localStorage.removeItem('ultimo-tratto-run-v2');meta.paths=undefined;pathMapIdx=0;startMap('pagina');ink=900;selected=1;build('triangle');phase='wave';enemies=[];queue=[];const sp=slot(1);let bt2=0,bd=1e9;for(let t=0;t<pathData(0).len;t+=2){const q=pathAt(pathData(0),t);const d=Math.hypot(q.x-sp.x,q.y-sp.y);if(d<bd){bd=d;bt2=t}}pathLoad=[];const pack=[];for(let i=0;i<8;i++){const e=spawnPathEnemy('pink',0,bt2);pack.push(e)}for(const e of pack)updatePathEnemy(e,.05);assert(pack.filter(e=>e.biting).length===BITE_CAP,'only '+BITE_CAP+' erasers stop at one defense, got '+pack.filter(e=>e.biting).length);assert(pack.filter(e=>!e.biting).every(e=>e.t>bt2),'the others keep walking along the path');console.log('PASS: erasers share out the defenses (cap per defense)')`);
test(`startMap('pagina');assert(introFly&&introFly.dur>3,'a flight from the start to the goal opens each map');cv.setPointerCapture=()=>{};cv.onpointerdown({pointerId:9,clientX:10,clientY:10,preventDefault(){}});assert(!introFly&&camera.zoom===1,'a tap skips the flight');startMap('pagina');for(let i=0;i<400;i++)stepIntro(.02);assert(!introFly&&camera.zoom===1&&Math.abs(camera.panX)<1e-6,'the flight ends on the home view');started=true;over=false;paused=false;gestureLocked=false;mixedTouchLock=false;resetContacts();const ev=(id,x,y)=>({pointerId:id,clientX:x,clientY:y,preventDefault(){}});cv.setPointerCapture=()=>{};const before=camera.panX;cv.onpointerdown(ev(1,200,300));cv.onpointermove(ev(1,215,300));cv.onpointermove(ev(1,260,320));assert(camera.panX>before+20,'one finger drags the view on the path map');cv.onpointerup(ev(1,260,320));assert(selected===-1,'a pan is not a tap');startGame('campaign','grid');const w=coords({clientX:0,clientY:0});const far={x:CX,y:CY};resetContacts();const px=camera.panX;const sc=view.scale;cv.onpointerdown(ev(2,view.x+(CX+170)*sc,view.y+CY*sc));cv.onpointermove(ev(2,view.x+(CX+170)*sc+30,view.y+CY*sc));assert(pointers.size===1&&camera.panX===px,'near the ring one finger still repairs');cv.onpointerup(ev(2,view.x+(CX+170)*sc+30,view.y+CY*sc));resetContacts();cv.onpointerdown(ev(3,view.x+(CX-340)*sc,view.y+(CY-260)*sc));cv.onpointermove(ev(3,view.x+(CX-340)*sc+20,view.y+(CY-260)*sc));cv.onpointermove(ev(3,view.x+(CX-340)*sc+60,view.y+(CY-260)*sc+10));assert(pointers.size===0&&camera.panX!==px,'away from the ring one finger pans in endless');cv.onpointerup(ev(3,0,0));console.log('PASS: one-finger camera pan (paths, endless away from the ring)')`)
